param([ValidateSet('trufor','mvss','both')][string]$Model='both',[int]$Gpu=0)
$ErrorActionPreference='Stop'; $Repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; $Inputs=Join-Path $Repo 'results\coverage_full_stress_inputs'
& python (Join-Path $PSScriptRoot 'prepare_coverage_full_stress.py'); if($LASTEXITCODE){throw 'Input preparation failed'}
if($Model -in @('trufor','both')) { $Python=Join-Path $Repo 'external\TruFor\.venv\Scripts\python.exe';$Src=Join-Path $Repo 'external\TruFor\test_docker\src';Push-Location $Src;try{foreach($C in @('jpeg_q80','jpeg_q40','resize_0.5','resize_0.25')){foreach($K in @('authentic','tampered')){$in=Join-Path (Join-Path (Join-Path $Inputs $C) $K) '*.jpg';$out=Join-Path (Join-Path (Join-Path $Repo 'results\trufor_coverage_full_stress_outputs') $C) $K;& $Python trufor_test.py -gpu $Gpu -in $in -out $out;if($LASTEXITCODE){throw "TruFor failed $C/$K"}}}}finally{Pop-Location}}
if($Model -in @('mvss','both')) {foreach($C in @('jpeg_q80','jpeg_q40','resize_0.5','resize_0.25')){foreach($K in @('authentic','tampered')){$in=Join-Path (Join-Path (Join-Path $Inputs $C) $K) '*.jpg';$out=Join-Path (Join-Path (Join-Path $Repo 'results\mvss_coverage_full_stress_outputs') $C) $K;& python (Join-Path $PSScriptRoot 'run_mvss_inference.py') --input $in --output $out --gpu $Gpu;if($LASTEXITCODE){throw "MVSS failed $C/$K"}}}}
